# Solid variant, used only where a filled glyph reads better (large status icons).
_CHECK_CIRCLE_SOLID = '<path fill-rule="evenodd" d="M2.25 12c0-5.385 4.365-9.75 9.75-9.75s9.75 4.365 9.75 9.75-4.365 9.75-9.75 9.75S2.25 17.385 2.25 12Zm13.36-1.814a.75.75 0 1 0-1.22-.872l-3.236 4.53L9.53 12.22a.75.75 0 0 0-1.06 1.06l2.25 2.25a.75.75 0 0 0 1.14-.094l3.75-5.25Z" clip-rule="evenodd"/>'


def _svg(inner, css_class, solid=False):
    fill = "currentColor" if solid else "none"
    stroke = "none" if solid else "currentColor"
    return mark_safe(
        f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="{fill}" '
        f'stroke="{stroke}" stroke-width="1.5" aria-hidden="true" class="{css_class}">{inner}</svg>'
    )


@register.simple_tag
def icon(name, css_class="w-5 h-5"):
    """Renders an inline Heroicons-outline SVG. Usage: {% icon 'home' 'w-4 h-4' %}"""
    if name == "check-circle-solid":
        return _svg(_CHECK_CIRCLE_SOLID, css_class, solid=True)
    inner = _PATHS.get(name)
    if inner is None:
        return ""
    return _svg(inner, css_class)
